def table(doc,headers,rows):
    t=doc.add_table(rows=1,cols=len(headers));t.style='Light Shading Accent 1'
    for c,h in zip(t.rows[0].cells,headers):c.text=h
    for row in rows:
        for c,v in zip(t.add_row().cells,row):c.text=human_spacing(str(v))
    for row in t.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                p.paragraph_format.space_after=Pt(4)
                for run in p.runs:run.font.name='Arial';run.font.size=Pt(9)
            tcPr=cell._tc.get_or_add_tcPr();m=OxmlElement('w:tcMar')
            for side in ['top','left','bottom','right']:
                z=OxmlElement('w:'+side);z.set(qn('w:w'),'80');z.set(qn('w:type'),'dxa');m.append(z)
            tcPr.append(m)
    # Repeat table headers and avoid splitting individual rows over pages.
    trPr=t.rows[0]._tr.get_or_add_trPr();repeat=OxmlElement('w:tblHeader');trPr.append(repeat)
    for row in t.rows:
        trPr=row._tr.get_or_add_trPr();keep=OxmlElement('w:cantSplit');trPr.append(keep)
    return t

def build():
    doc=Document();doc.core_properties.title=TITLE;doc.core_properties.subject='Regional niche remodeling and asynchronous postnatal cardiac development'
    doc.core_properties.author='Heart atlas analysis';doc.core_properties.keywords='postnatal heart; spatial transcriptomics; fibroblast; endothelial; cardiomyocyte; optimal transport; Wormhole'
    doc.core_properties.created=datetime.datetime(2026,10,26,12,0,0,tzinfo=datetime.timezone.utc)
    doc.core_properties.modified=datetime.datetime(2026,10,26,12,0,0,tzinfo=datetime.timezone.utc)
    s=doc.sections[0];s.page_width=Inches(8.5);s.page_height=Inches(11)
    s.top_margin=Inches(.65);s.bottom_margin=Inches(.65);s.left_margin=Inches(.7);s.right_margin=Inches(.7)
    s.header_distance=Inches(.25);s.footer_distance=Inches(.25);s.different_first_page_header_footer=True
    normal=doc.styles['Normal'];normal.font.name='Cambria';normal.font.size=Pt(11);normal.paragraph_format.line_spacing=1.1;normal.paragraph_format.space_after=Pt(7)
    for name in ['Heading 1','Heading 2','Title']:
        doc.styles[name].font.name='Arial';doc.styles[name].font.color.rgb=RGBColor.from_string('203C54')
    doc.styles['Heading 1'].font.size=Pt(15);doc.styles['Heading 2'].font.size=Pt(11.5)
    doc.styles['Heading 1'].paragraph_format.space_before=Pt(15)
    hp=s.header.paragraphs[0];hp.text='POSTNATAL CARDIAC DEVELOPMENT  |  INTEGRATED SECONDARY ANALYSIS'
    for r in hp.runs:r.font.name='Arial';r.font.size=Pt(8);r.font.color.rgb=RGBColor.from_string('52606D')
    foot=s.footer.paragraphs[0];foot.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    r=foot.add_run();field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');r._r.addnext(field)
    settings=doc.settings.element;update=OxmlElement('w:updateFields');update.set(qn('w:val'),'true');settings.append(update)
    p=doc.add_paragraph();p.paragraph_format.space_before=Pt(24)
    r=p.add_run('RESEARCH MANUSCRIPT • EVIDENCE-LINKED DRAFT');r.font.name='Arial';r.font.size=Pt(9);r.font.bold=True;r.font.color.rgb=RGBColor.from_string('4477AA')
    p=doc.add_paragraph(TITLE,'Title');p.paragraph_format.space_after=Pt(15)
    for r in p.runs:r.font.size=Pt(24)
    p=doc.add_paragraph(SUBTITLE);p.paragraph_format.space_after=Pt(18)
    doc.add_heading('Central message',2);doc.add_paragraph(CENTRAL)
    p=doc.add_paragraph('This document develops an additional interpretation of the deposited Heart Atlas data. It contains six integrated figure plates, source-linked results, candidate state continuities and a functional validation roadmap. Proposed transitions and mechanisms are identified as hypotheses.');p.paragraph_format.space_after=Pt(14)
    table(doc,['Evidence represented','Boundary of interpretation'],[
        ['Observed RNA and spatial patterns','Four ages; one available spatial section per age'],
        ['Candidate subtype continuity','RNA resemblance and neighborhood correspondence; no tracked ancestry'],
        ['Proposed causal mechanisms','Functional and lineage-tracing experiments remain to be performed']])
    p=doc.add_paragraph('Prepared 26 October 2026 • Source data, count views and analysis provenance accompany the figures.');p.paragraph_format.space_before=Pt(15)
    for r in p.runs:r.font.size=Pt(9);r.font.color.rgb=RGBColor.from_string('52606D')
    doc.add_page_break()
    for title,paragraphs in SECTIONS:
        level=1 if title in ['Abstract','Introduction','Results','Discussion','Methods'] else 2
        if title in ['Introduction','Discussion','Methods']:doc.add_page_break()
        doc.add_heading(title,level)
        for p in paragraphs:doc.add_paragraph(human_spacing(p))
    doc.add_heading('Data and code availability',1)
    doc.add_paragraph('All new figure plates, editable vector exports, source-data tables, restricted transport correspondences, validation and manuscript-generation scripts are provided in results/cardiac_developmental_story and analysis/. The complete primary count/reference objects remain linked through upstream provenance. Public data derivatives retain attribution to the original authors. The uploaded journal PDFs are not redistributed. The original atlas authors’ unpublished anatomical masks, maturation-score objects and neighbor table are not claimed to have been recovered.')
    doc.add_heading('References',1)
    for n,title,url in REFERENCES:doc.add_paragraph(human_spacing(f'{n}. {title} {url}'))
    doc.add_page_break();doc.add_heading('Evidence-to-claim map',1)
    claims=[
      ['Recurring spatial organization','Fig.1; broad annotations/contact nulls','Observed across the available sections','No unbiased abundance census or exhaustive niche taxonomy'],
      ['Persistent regional CM identity','Fig.2; Slit2/endocardial comparison','Descriptive regional association','No verified Purkinje identity or Kcnd2 gradient'],
      ['Fibroblast matrix specialization','Fig.3; reviewed RNA and local context','Observed transcriptional/context differences','No direct ECM deposition or stiffness measurement'],
      ['Possible subtype continuity','Fig.3f; gene-withheld RNA resemblance','Candidate transition hypothesis','No conversion rate, ancestry or cell tracking'],
      ['Stage-contingent vascular association','Fig.4; nuclear and matched components','Within-section exploratory associations','No independent-heart age interaction or causal timing switch'],
      ['Neighborhood remodeling','Fig.5; exact OT and calibrated Wormhole','Distributional similarity and correspondence sensitivity','No unique fate map, absolute expansion or temporal rate'],
      ['Regional multicellular developmental model','Fig.6; integrated observations','Testable biological model','Functional and lineage validation required']]
    table(doc,['Claim','Evidence','Status','Limit'],claims)
    doc.add_heading('What this adds beyond the atlas',2)
    table(doc,['Starting point in the atlas','Additional question addressed here'],[
       ['Cell-state maps and a composite CM maturation relationship','Separate persistent regional identity from local response states and different maturation components'],
       ['Fibroblast classes','Current reviewed families, matrix-program specialization, partial vascular context and candidate continuity'],
       ['Vascular/microenvironment association','Distinguish EC cycling, capillary access and operational boundary apposition'],
       ['Spatial contexts at observed ages','Calibrated exact/Wormhole comparisons show both internal heterogeneity and uncertainty of fine correspondence']])
    doc.add_heading('Specific experiments and decision points',1)
    table(doc,['Hypothesis','Discriminating study','Result that would change the interpretation'],[
       ['Regional identity persists beyond a global maturation axis','Multiplex CM/EC imaging with matched wall geometry and component scores','The regional difference disappears after appropriate anatomical/state matching'],
       ['Some early fibroblast states contribute to later matrix-specialized states','Validated inducible early-FB lineage label; serial P7/P14/P21 state/spatial readout','Later families arise predominantly outside the labeled population'],
       ['Oxygen delivery and EC contact affect distinct CM components','Oxygen×contact×initial-CM-state factorial design with fixed matrix/EC number','No reproducible functional effect at matched viability and baseline state'],
       ['EC-specific contact signaling contributes after integration','Conditional on contact benefit: EC-specific candidate perturbation/rescue; reciprocal CM test','Contact effect persists despite verified perturbation with preserved EC support'],
       ['Intermediate development contains identifiable remodeling windows','Independent hearts at P3/P5 and around P10, matched anatomical sections and vascular-function imaging','Additional stages do not support the proposed sequence or reveal alternative regional paths']])
    doc.add_paragraph('Pilot functional experiments should use at least four independent donor preparations per initial CM state, with treatments paired within donor. Confirmation must be powered from between-donor variability. This is a design recommendation, not a completed experiment or an established sample-size calculation.')
    # Each figure plate gets a dedicated page; full legends follow all plates.
    for i,(stem,title,legend) in enumerate(LEGENDS,1):
        doc.add_page_break();doc.add_heading(f'Figure {i} | {title}',2)
        path=OUT/'figures'/(stem+'.png')
        with Image.open(path) as im:w,h=im.size
        width=min(7.05,8.45*w/h)
        p=doc.add_paragraph();p.paragraph_format.space_after=Pt(0);p.paragraph_format.line_spacing=1
        p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run().add_picture(str(path),width=Inches(width))
        p=doc.add_paragraph(f'Integrated panel plate. Detailed legend and interpretation limits appear in the figure-legends section. Source data and editable PDF/SVG exports accompany this document.');p.paragraph_format.space_after=Pt(0)
        for r in p.runs:r.font.size=Pt(8)
    doc.add_page_break();doc.add_heading('Figure legends',1)
    for i,(stem,title,legend) in enumerate(LEGENDS,1):
        doc.add_heading(f'Figure {i}. {title}',2);doc.add_paragraph(human_spacing(legend))
    path=OUT/'Postnatal_cardiac_development_manuscript.docx';doc.save(path)
    md=[f'# {TITLE}',SUBTITLE,'**Central message.** '+CENTRAL,'']
    for title,paragraphs in SECTIONS:md+=['## '+title,'',*sum(([human_spacing(p),''] for p in paragraphs),[])]
    md+=['## References','']+[human_spacing(f'{n}. {title} {url}') for n,title,url in REFERENCES]
    md+=['','## Integrated figures','']
    for i,(stem,title,legend) in enumerate(LEGENDS,1):md +=[f'### Figure {i}. {title}',f'![Figure {i}](figures/{stem}.png)',human_spacing(legend),'']
    (OUT/'Manuscript_text.md').write_text('\n'.join(md).rstrip()+'\n')
    (OUT/'manuscript_structure.json').write_text(json.dumps({'title':TITLE,'central_message':CENTRAL,'sections':[t for t,_ in SECTIONS],
        'main_figure_plates':6,'data_scope':'Secondary analysis, one spatial section/age, no new biological replication',
        'manuscript_words':len(' '.join(p for _,ps in SECTIONS for p in ps).split()),'figures':[s for s,_,_ in LEGENDS],
        'editable_Word':True,'source_text':'Manuscript_text.md'},indent=2)+'\n')
    with zipfile.ZipFile(path) as z:
        xml=z.read('word/document.xml').decode();assert xml.count('<pic:pic>')==6
    print('WORD_MANUSCRIPT_CREATED',path,flush=True)

if __name__=='__main__':build()
